{"content":"// ============================================================================
// Print-in-Place Articulated Butterfly Model (FDM 3D Printable)
// ============================================================================
// Coordinate System:
//   X-axis : Torso longitudinal direction (+X = Head/Antennae, -X = Abdomen)
//   Y-axis : Wing span direction (+Y = Left Wing, -Y = Right Wing)
//   Z-axis : Vertical print direction (Z = 0 is flat on the build plate)
//
// Structure:
//   3 Rigid Bodies:
//     1. Fixed Torso (parts_1.stl): Head, eyes, antennae, thorax, abdomen,
//        and left/right captive double-conical pin joints with gothic-arch bridges.
//     2. Left Wing (parts_2.stl): 360-degree captive bore hub + forewing/hindwing
//        with raised venation texture and decorative cellular cutouts.
//     3. Right Wing (parts_3.stl): Mirror-symmetric right wing.
//
// Printing Parameters Target:
//   PLA, 0.4 mm nozzle, 0.2 mm layer height, no supports required.
//   Pin-to-bore single-side radial clearance: 0.50 mm (within 0.4 - 0.6 mm).
// ============================================================================

$fn = 80;

// ----------------------------
// Render / Export Control
// ----------------------------
// Options: "all", "torso", "left_wing", "right_wing"
part_select = "all";

// Wing rotation angles in degrees (Valid collision-free range: <= -30 to >= +30)
left_wing_angle  = 0;
right_wing_angle = 0;

// ----------------------------
// Core Joint Parameters (mm)
// ----------------------------
joint_x = 2.0;               // Joint axis X position
joint_y = 10.5;              // Joint axis |Y| position (Left = +10.5, Right = -10.5)

radial_clearance = 0.50;     // Single-side radial clearance (0.4 - 0.6 mm spec)
axial_clearance  = 0.68;     // Minimum vertical Z clearance in gothic arch

pin_shaft_r      = 3.00;     // Central cylindrical pin radius (D = 6.00 mm)
pin_flare_r      = 4.30;     // Bottom/top conical retention flare radius (D = 8.60 mm)
bore_shaft_r     = pin_shaft_r + radial_clearance; // 3.50 mm (D = 7.00 mm)
bore_flare_r     = pin_flare_r + radial_clearance; // 4.80 mm (D = 9.60 mm)

knuckle_outer_r  = 7.20;     // Outer radius of wing knuckle ring (D = 14.40 mm)
torso_clear_r    = knuckle_outer_r + radial_clearance; // 7.70 mm

// Z-height levels (aligned to 0.20 mm layer increments)
z_bed            = 0.00;
z_skirt_top      = 0.80;     // Vertical base skirt top
z_bot_cone_top   = 2.40;     // Bottom conical retention top (dZ = 1.60, dR = 1.30 -> 50.9 deg)
z_mid_cyl_top    = 6.00;     // Central cylindrical shaft top (height = 3.60 mm)
z_top_cone_top   = 7.60;     // Top conical retention top (dZ = 1.60, dR = 1.30 -> 50.9 deg)
z_knuckle_top    = 8.60;     // Top of wing knuckle roof (dZ = 1.00, slope = 51.3 deg)
z_arch_merge     = 9.80;     // Gothic arch merge height (dZ = 2.20, dR = 1.70 -> 52.3 deg)
z_bridge_top     = 12.60;    // Top of torso shoulder bridge & pin cap

// Wing thickness parameters
wing_base_h      = 3.00;     // Main wing membrane/frame thickness
wing_vein_h      = 4.20;     // Raised decorative vein & border height

// ============================================================================
// Helper Modules
// ============================================================================

// Smooth 2D polygon rounding via offset
module smooth_2d(r_round = 1.5) {
    offset(r = r_round)
    offset(r = -2 * r_round)
    offset(r = r_round)
        children();
}

// 2D capsule between two points with end radii r1, r2
module bar_2d(p1, p2, r1, r2 = -1) {
    r_end = (r2 < 0) ? r1 : r2;
    hull() {
        translate(p1) circle(r = r1);
        translate(p2) circle(r = r_end);
    }
}

// 3D tapered capsule segment flat on Z=0 with 45-deg beveled top
module sculpted_segment(p1, p2, r1, r2, h1, h2) {
    hull() {
        translate([p1[0], p1[1], 0])
            cylinder(r1 = r1, r2 = max(0.6, r1 - 0.35 * h1), h = h1);
        translate([p2[0], p2[1], 0])
            cylinder(r1 = r2, r2 = max(0.6, r2 - 0.35 * h2), h = h2);
    }
}

// ============================================================================
// Joint Profiles & Modules
// ============================================================================

// 360-degree Captive Pin (Part of Fixed Torso)
module captive_pin() {
    rotate_extrude(angle = 360) {
        polygon(points = [
            [0.00,         z_bed],
            [pin_flare_r,  z_bed],
            [pin_flare_r,  z_skirt_top],
            [pin_shaft_r,  z_bot_cone_top],
            [pin_shaft_r,  z_mid_cyl_top],
            [pin_flare_r,  z_top_cone_top],
            [pin_flare_r,  z_bridge_top - 0.80],
            [pin_flare_r - 0.80, z_bridge_top],
            [0.00,         z_bridge_top]
        ]);
    }
}

// Torso Gothic-Arch Bridge connecting the Captive Pin to the Thorax Shoulder
// Spans a 100-degree angular sector on the inner (torso-facing) side of the joint.
module torso_shoulder_arch(is_left = true) {
    start_ang = is_left ? -140 : 40;
    union() {
        rotate([0, 0, start_ang])
        rotate_extrude(angle = 100) {
            polygon(points = [
                // Start at outer shoulder wall on bed
                [torso_clear_r, z_bed],
                [joint_y,       z_bed],
                [joint_y,       z_bridge_top - 0.80],
                [joint_y - 0.80, z_bridge_top],
                // Across top of bridge to pin center
                [pin_flare_r - 0.80, z_bridge_top],
                [pin_flare_r,   z_bridge_top - 0.80],
                [pin_flare_r,   z_top_cone_top],
                // Gothic arch apex (52.3 deg self-supporting slopes from both sides)
                [6.00,          z_arch_merge],
                [torso_clear_r, z_top_cone_top]
            ]);
        }
        // Smooth transition fairing into the central thorax body
        hull() {
            translate([0, is_left ? -joint_y : joint_y, 0])
                cylinder(r1 = 5.2, r2 = 3.8, h = z_bridge_top);
            translate([0, is_left ? -8.5 : 8.5, 0])
                cylinder(r1 = 4.2, r2 = 3.0, h = z_bridge_top);
        }
    }
}

// Clearance cutout subtracted from the Torso around each joint before adding the Pin
module wing_knuckle_clearance_cutout() {
    rotate_extrude(angle = 360) {
        polygon(points = [
            [0.00,          z_bed - 0.1],
            [torso_clear_r, z_bed - 0.1],
            [torso_clear_r, z_top_cone_top],
            [6.00,          z_arch_merge],
            [pin_flare_r,   z_top_cone_top],
            [0.00,          z_top_cone_top]
        ]);
    }
    // Outer swing clearance outside the 100-deg bridge sector
    // Ensures nothing on the torso above z_top_cone_top blocks the wing root
    rotate_extrude(angle = 360) {
        polygon(points = [
            [pin_flare_r + 0.01, z_bed - 0.1],
            [torso_clear_r,      z_bed - 0.1],
            [torso_clear_r,      z_top_cone_top],
            [6.00,               z_arch_merge],
            [pin_flare_r + 0.01, z_top_cone_top]
        ]);
    }
}

// 360-degree Wing Knuckle Hub with Captive Double-Conical Bore (Part of Wing)
module wing_knuckle_solid() {
    rotate_extrude(angle = 360) {
        polygon(points = [
            [bore_flare_r,    z_bed],
            [knuckle_outer_r, z_bed],
            [knuckle_outer_r, z_top_cone_top],
            [6.40,            z_knuckle_top],
            [5.60,            z_knuckle_top],
            [bore_flare_r,    z_top_cone_top],
            [bore_shaft_r,    z_mid_cyl_top],
            [bore_shaft_r,    z_bot_cone_top],
            [bore_flare_r,    z_skirt_top]
        ]);
    }
}

// ============================================================================
// Part 1: Fixed Butterfly Torso (Head, Eyes, Antennae, Thorax, Abdomen, Pins)
// ============================================================================

module butterfly_torso() {
    union() {
        difference() {
            union() {
                // 1. Central Thorax (mesothorax & metathorax sculpted dome)
                sculpted_segment([-5.5, 0], [12.5, 0], 5.6, 6.2, 11.2, 12.6);
                sculpted_segment([1.0,  0], [8.0,  0], 6.8, 6.5, 12.6, 12.6);

                // Dorsal thoracic crest details
                translate([3.5, 0, 12.2])
                    scale([1.8, 0.85, 0.45])
                    sphere(r = 3.2);
                translate([-2.0, 0, 11.2])
                    scale([1.5, 0.80, 0.40])
                    sphere(r = 2.8);

                // 2. Left & Right Shoulder Bridges
                translate([joint_x,  joint_y, 0]) torso_shoulder_arch(is_left = true);
                translate([joint_x, -joint_y, 0]) torso_shoulder_arch(is_left = false);

                // 3. Prothorax Neck & Head Capsule (+X)
                sculpted_segment([12.5, 0], [18.5, 0], 4.8, 5.2, 10.5, 9.6);

                // Compound Eyes (left & right prominent spheres integrated to bed)
                for (sy = [-1, 1]) {
                    hull() {
                        translate([19.2, sy * 3.4, 0])
                            cylinder(r1 = 2.6, r2 = 2.8, h = 6.5);
                        translate([19.5, sy * 3.6, 6.2])
                            sphere(r = 2.7);
                    }
                }

                // 4. Clubbed Antennae (flat on Z=0 for reliable bed adhesion)
                for (sy = [-1, 1]) {
                    linear_extrude(height = 3.4, scale = 0.88) {
                        union() {
                            bar_2d([20.5, sy * 2.0], [26.0, sy * 3.2], 1.35, 1.25);
                            bar_2d([26.0, sy * 3.2], [31.5, sy * 5.0], 1.25, 1.30);
                            bar_2d([31.5, sy * 5.0], [34.8, sy * 6.0], 1.30, 2.05);
                        }
                    }
                }

                // 5. Segmented Abdomen (-X, 7 anatomical segments tapering to tail)
                sculpted_segment([-5.5,  0], [-11.0, 0], 5.2, 5.0, 10.2, 9.6);
                sculpted_segment([-11.0, 0], [-16.5, 0], 5.1, 4.8, 9.6,  9.0);
                sculpted_segment([-16.5, 0], [-22.0, 0], 4.9, 4.5, 9.0,  8.4);
                sculpted_segment([-22.0, 0], [-27.5, 0], 4.6, 4.1, 8.4,  7.6);
                sculpted_segment([-27.5, 0], [-32.5, 0], 4.2, 3.5, 7.6,  6.8);
                sculpted_segment([-32.5, 0], [-37.0, 0], 3.6, 2.7, 6.8,  5.8);
                sculpted_segment([-37.0, 0], [-40.5, 0], 2.8, 1.8, 5.8,  4.6);

                // Abdominal annular ridges (textured rings on top of abdomen)
                for (i = [0 : 5]) {
                    seg_x = -8.5 - i * 5.2;
                    seg_r = 4.9 - i * 0.42;
                    seg_h = 9.8 - i * 0.72;
                    translate([seg_x, 0, 0])
                        cylinder(r1 = seg_r, r2 = seg_r - 1.2, h = seg_h + 0.5);
                }
            }

            // Subtract Wing Knuckle clearance envelope on both sides
            translate([joint_x,  joint_y, 0]) wing_knuckle_clearance_cutout();
            translate([joint_x, -joint_y, 0]) wing_knuckle_clearance_cutout();

            // Outer radial swing clearance beyond torso_clear_r in the wing sweep sector
            for (sy = [-1, 1]) {
                translate([joint_x, sy * joint_y, -0.1])
                rotate([0, 0, (sy > 0) ? -40 : 140])
                rotate_extrude(angle = 260) {
                    polygon(points = [
                        [0.0,           0.0],
                        [torso_clear_r, 0.0],
                        [torso_clear_r, z_bridge_top + 1.0],
                        [0.0,           z_bridge_top + 1.0]
                    ]);
                }
            }

            // Ensure strictly flat bottom on Z = 0
            translate([-60, -60, -10])
                cube([120, 120, 10]);
        }

        // Add the Left and Right Captive Pins
        translate([joint_x,  joint_y, 0]) captive_pin();
        translate([joint_x, -joint_y, 0]) captive_pin();
    }
}

// ============================================================================
// Parts 2 & 3: Left and Right Movable Butterfly Wings
// ============================================================================

// Complete 2D Left Wing Silhouette (in global XY coordinates for neutral pose)
// Designed so every point outside the knuckle lies in polar angle [39 deg, 150 deg]
// relative to (joint_x, joint_y) = (2.0, 10.5), guaranteeing Y >= 10.5 mm throughout
// the entire [-30 deg, +30 deg] swing range!
module left_wing_outer_2d() {
    smooth_2d(r_round = 1.6) {
        polygon(points = [
            // Root hub attachment (centered at joint_x=2.0, joint_y=10.5)
            [ 2.0, 11.5],
            [ 6.2, 14.5],
            // Forewing costal (leading) margin (polar angle >= 39.5 deg)
            [14.0, 20.8],
            [24.0, 29.0],
            [33.5, 37.5],
            // Forewing apex
            [39.5, 43.2],
            [38.5, 45.8],
            // Forewing outer scalloped margin (max Y <= 46.8 mm)
            [31.0, 46.6],
            [23.0, 45.5],
            [16.0, 43.2],
            [10.0, 39.8],
            // Forewing / Hindwing division notch
            [ 4.2, 34.5],
            // Hindwing outer scalloped margin
            [-2.5, 38.8],
            [-10.5, 40.2],
            [-18.5, 38.8],
            [-25.0, 35.8],
            // Swallowtail hindwing lobe
            [-31.5, 32.2],
            [-29.0, 28.8],
            // Hindwing inner (trailing) margin (polar angle <= 150 deg)
            [-23.5, 25.5],
            [-15.0, 20.6],
            [-7.5,  16.5],
            [-2.2,  14.2]
        ]);
    }
}

// Decorative wing cell cutouts (subtracted from the base membrane between veins)
module left_wing_cutouts_2d() {
    // 1. Forewing large discal cell window
    hull() {
        translate([13.5, 25.5]) circle(r = 2.0);
        translate([22.5, 33.0]) circle(r = 2.8);
        translate([17.5, 35.5]) circle(r = 2.4);
    }
    // 2. Forewing apical sub-cells
    hull() {
        translate([28.0, 37.5]) circle(r = 1.6);
        translate([33.5, 41.8]) circle(r = 1.5);
    }
    hull() {
        translate([24.5, 40.5]) circle(r = 1.8);
        translate([30.0, 43.0]) circle(r = 1.6);
    }
    hull() {
        translate([16.5, 39.8]) circle(r = 1.8);
        translate([21.0, 41.8]) circle(r = 1.6);
    }
    // 3. Hindwing central discal cell window
    hull() {
        translate([-2.5, 23.0]) circle(r = 2.0);
        translate([-10.5, 29.5]) circle(r = 2.6);
        translate([-5.0, 31.5]) circle(r = 2.2);
    }
    // 4. Hindwing outer marginal cells
    hull() {
        translate([-13.5, 34.5]) circle(r = 1.8);
        translate([-19.0, 34.2]) circle(r = 1.6);
    }
    hull() {
        translate([-17.5, 28.5]) circle(r = 1.7);
        translate([-24.5, 30.8]) circle(r = 1.4);
    }
}

// Raised 2D Venation Pattern & Ornamental Eye-Spots (extruded up to wing_vein_h)
module left_wing_veins_2d() {
    union() {
        // Outer perimeter border frame (1.8 mm wide rim)
        difference() {
            left_wing_outer_2d();
            offset(r = -1.8) left_wing_outer_2d();
        }

        // Rim around every cutout cell (1.2 mm wide reinforcement rib)
        difference() {
            offset(r = 1.2) left_wing_cutouts_2d();
            left_wing_cutouts_2d();
        }

        // Main primary radial veins from wing root hub (6.0, 18.5)
        bar_2d([4.5, 16.5], [13.5, 23.5], 1.3, 1.0);
        bar_2d([13.5, 23.5], [37.5, 43.5], 1.0, 0.8); // Subcostal / Radial vein
        bar_2d([15.5, 28.5], [30.5, 45.5], 0.9, 0.8); // Median vein 1
        bar_2d([12.5, 31.5], [22.0, 44.5], 0.9, 0.8); // Median vein 2
        bar_2d([6.5,  22.5], [14.5, 42.0], 1.0, 0.8); // Cubital vein
        bar_2d([3.5,  18.5], [4.5,  34.5], 1.1, 0.9); // Fore/hind divider vein

        // Hindwing radial veins
        bar_2d([1.0, 17.5], [-4.5,  38.0], 1.1, 0.8);
        bar_2d([0.0, 17.0], [-12.5, 39.2], 1.1, 0.8);
        bar_2d([-0.5, 16.5], [-21.0, 37.5], 1.1, 0.8);
        bar_2d([-1.0, 16.0], [-29.5, 31.5], 1.1, 0.8); // Swallowtail vein

        // Decorative raised eye-spot rings
        translate([9.8, 35.2])
        difference() {
            circle(r = 2.8);
            circle(r = 1.2);
        }
        translate([-7.0, 35.2])
        difference() {
            circle(r = 2.8);
            circle(r = 1.2);
        }
    }
}

// Complete Left Wing 3D Solid in Neutral Pose
module left_wing_neutral() {
    union() {
        // 1. 360-degree Captive Knuckle Hub centered at (joint_x, joint_y)
        translate([joint_x, joint_y, 0])
            wing_knuckle_solid();

        // 2. Wing Blade & Root Gusset (trimmed strictly outside the knuckle bore)
        difference() {
            union() {
                // Base wing plate (Z = 0 to 3.0 mm) with decorative cell cutouts
                linear_extrude(height = wing_base_h) {
                    difference() {
                        left_wing_outer_2d();
                        left_wing_cutouts_2d();
                    }
                }

                // Raised venation texture & border frame (Z = 0 to 4.2 mm)
                linear_extrude(height = wing_vein_h) {
                    intersection() {
                        left_wing_outer_2d();
                        left_wing_veins_2d();
                    }
                }

                // Structural root gusset smoothly blending knuckle height (7.6 mm)
                // into the wing blade root (4.2 mm) within the safe outer sector
                hull() {
                    intersection() {
                        translate([joint_x, joint_y, 0])
                            cylinder(r = knuckle_outer_r, h = z_top_cone_top);
                        translate([joint_x - 3.5, joint_y + 2.5, 0])
                            cube([9.0, 10.0, z_top_cone_top]);
                    }
                    translate([3.2, 18.8, 0])
                        cylinder(r1 = 4.2, r2 = 2.8, h = 5.4);
                }
            }

            // Ensure the bore and clearance around the pin & torso arch are 100% unobstructed
            translate([joint_x, joint_y, 0])
            rotate_extrude(angle = 360) {
                polygon(points = [
                    [0.00,             -1.0],
                    [knuckle_outer_r - 0.05, -1.0],
                    [knuckle_outer_r - 0.05, z_top_cone_top + 0.02],
                    [6.40,             z_knuckle_top + 0.02],
                    [knuckle_outer_r + 3.0, z_knuckle_top + 0.02],
                    [knuckle_outer_r + 3.0, z_bridge_top + 2.0],
                    [0.00,             z_bridge_top + 2.0]
                ]);
            }
        }
    }
}

// Left Wing with rotation applied around (joint_x, +joint_y)
module left_wing_positioned(angle_deg = 0) {
    translate([joint_x, joint_y, 0])
    rotate([0, 0, angle_deg])
    translate([-joint_x, -joint_y, 0])
        left_wing_neutral();
}

// Right Wing with rotation applied around (joint_x, -joint_y)
// Exact mirror of Left Wing across the XZ plane (Y = 0)
module right_wing_positioned(angle_deg = 0) {
    translate([joint_x, -joint_y, 0])
    rotate([0, 0, angle_deg])
    translate([-joint_x, joint_y, 0])
    mirror([0, 1, 0])
        left_wing_neutral();
}

// ============================================================================
// Top-Level Assembly Dispatcher
// ============================================================================

if (part_select == "all") {
    butterfly_torso();
    left_wing_positioned(left_wing_angle);
    right_wing_positioned(right_wing_angle);
} else if (part_select == "torso") {
    butterfly_torso();
} else if (part_select == "left_wing") {
    left_wing_positioned(left_wing_angle);
} else if (part_select == "right_wing") {
    right_wing_positioned(right_wing_angle);
}
