// Raised 2D Venation Pattern & Ornamental Eye-Spots (extruded up to wing_vein_h)
module left_wing_veins_2d() {
    union() {
        // Outer perimeter border frame (1.8 mm wide rim)
        difference() {
            left_wing_outer_2d();
            offset(r = -1.8, $fn = 32) left_wing_outer_2d();
        }

        // Reinforcement border around recessed cells & through-windows
        difference() {
            offset(r = 1.1, $fn = 32) {
                left_wing_recessed_cells_2d();
                left_wing_through_windows_2d();
            }
            left_wing_recessed_cells_2d();
            left_wing_through_windows_2d();
        }

        // Primary radial veins radiating from root hub without crossing windows
        bar_2d([4.5, 16.5], [14.0, 22.0], 1.3, 1.0);
        bar_2d([14.0, 22.0], [37.5, 43.2], 1.0, 0.85); // Subcostal / Radial vein
        bar_2d([22.5, 32.5], [30.5, 45.2], 0.95, 0.80); // Radial branch 1
        bar_2d([18.5, 35.2], [21.8, 44.2], 0.95, 0.80); // Median branch 1
        bar_2d([6.5,  20.5], [16.5, 35.2], 1.1,  0.95); // Discal lower vein
        bar_2d([14.5, 36.8], [14.5, 42.2], 0.95, 0.80); // Cubital branch
        bar_2d([3.5,  18.5], [3.8,  33.8], 1.15, 0.90); // Fore/hind cleft vein

        // Hindwing radial veins between cells
        bar_2d([1.5,  18.0], [-2.5,  38.5], 1.1, 0.85);
        bar_2d([-0.5, 18.0], [-11.5, 39.8], 1.1, 0.85);
        bar_2d([-2.0, 17.5], [-20.0, 38.0], 1.1, 0.85);
        bar_2d([-3.0, 16.5], [-30.0, 31.8], 1.1, 0.85); // Swallowtail vein

        // Decorative raised eye-spot rings
        translate([6.2, 34.2])
        difference() {
            circle(r = 2.4, $fn = 40);
            circle(r = 1.0, $fn = 40);
        }
        translate([-1.5, 36.2])
        difference() {
            circle(r = 2.4, $fn = 40);
            circle(r = 1.0, $fn = 40);
        }
    }
}

// Complete Left Wing 3D Solid in Neutral Pose
module left_wing_neutral() {
    union() {
        // 1. 360-degree Captive Knuckle Hub centered at (joint_x, joint_y)
        translate([joint_x, joint_y, 0])
            wing_knuckle_solid();

        // 2. Wing Blade & Root Gusset (trimmed strictly outside the knuckle bore)
        difference() {
            union() {
                // Level 1: Continuous inner wing membrane floor (Z = 0 to 1.40 mm)
                linear_extrude(height = wing_cell_floor_h) {
                    difference() {
                        left_wing_outer_2d();
                        left_wing_through_windows_2d();
                    }
                }

                // Level 2: Main structural wing plate (Z = 0 to 2.80 mm)
                linear_extrude(height = wing_base_h) {
                    difference() {
                        left_wing_outer_2d();
                        left_wing_recessed_cells_2d();
                        left_wing_through_windows_2d();
                    }
                }

                // Level 3: Raised venation texture & border frame (Z = 0 to 4.00 mm)
                linear_extrude(height = wing_vein_h) {
                    intersection() {
                        left_wing_outer_2d();
                        difference() {
                            left_wing_veins_2d();
                            left_wing_through_windows_2d();
                        }
                    }
                }

                // Level 4: Smoothly contoured root gusset (clamped strictly inside wing silhouette)
                intersection() {
                    linear_extrude(height = z_top_cone_top)
                        left_wing_outer_2d();
                    hull() {
                        intersection() {
                            translate([joint_x, joint_y, 0])
                                cylinder(r = knuckle_outer_r - 0.1, h = z_top_cone_top - cone_z_clearance, $fn = 72);
                            translate([joint_x - 3.5, joint_y + 2.8, 0])
                                cube([9.0, 10.0, z_top_cone_top - cone_z_clearance]);
                        }
                        translate([3.5, 19.2, 0])
                            cylinder(r1 = 4.5, r2 = 2.8, h = 5.0, $fn = 40);
                    }
                }
            }

            // Ensure the bore and clearance around the pin & torso arch are 100% unobstructed
            translate([joint_x, joint_y, 0])
            rotate_extrude(angle = 360, $fn = 72) {
                polygon(points = [
                    [0.00,                   -1.0],
                    [knuckle_outer_r - 0.15, -1.0],
                    [knuckle_outer_r - 0.15, z_top_cone_top - cone_z_clearance + 0.05],
                    [6.40,                   z_knuckle_top + 0.05],
                    [knuckle_outer_r + 3.0,  z_knuckle_top + 0.05],
                    [knuckle_outer_r + 3.0,  z_bridge_top + 2.0],
                    [0.00,                   z_bridge_top + 2.0]
                ]);
            }
        }
    }
}

// Left Wing with rotation applied around (joint_x, +joint_y)
module left_wing_positioned(angle_deg = 0) {
    translate([joint_x, joint_y, 0])
    rotate([0, 0, angle_deg])
    translate([-joint_x, -joint_y, 0])
        left_wing_neutral();
}

// Right Wing with rotation applied around (joint_x, -joint_y)
// Exact mirror of Left Wing across the XZ plane (Y = 0)
module right_wing_positioned(angle_deg = 0) {
    translate([joint_x, -joint_y, 0])
    rotate([0, 0, angle_deg])
    translate([-joint_x, joint_y, 0])
    mirror([0, 1, 0])
        left_wing_neutral();
}

// ============================================================================
// Top-Level Assembly Dispatcher
// ============================================================================

if (part_select == "all") {
    butterfly_torso();
    left_wing_positioned(left_wing_angle);
    right_wing_positioned(right_wing_angle);
} else if (part_select == "torso") {
    butterfly_torso();
} else if (part_select == "left_wing") {
    left_wing_positioned(left_wing_angle);
} else if (part_select == "right_wing") {
    right_wing_positioned(right_wing_angle);
}
"}

